import{_ as e,o as t,c as s,ao as a}from"./chunks/framework.BqHBDjRx.js";const k=JSON.parse('{"title":"Making some cases more or less infectious","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/infectiousness.md","filePath":"tutorials/infectiousness.md","lastUpdated":null}'),n={name:"tutorials/infectiousness.md"};function o(r,i,h,d,c,l){return t(),s("div",null,[...i[0]||(i[0]=[a(`<h1 id="Making-some-cases-more-or-less-infectious" tabindex="-1">Making some cases more or less infectious <a class="header-anchor" href="#Making-some-cases-more-or-less-infectious" aria-label="Permalink to &quot;Making some cases more or less infectious {#Making-some-cases-more-or-less-infectious}&quot;">​</a></h1><p>Every route below sets one quantity: the rate at which a case infects others at each time since its infection. That rate is a baseline, multiplied by a factor for the person and by factors that events switch on. The package has four places to set it. Which one applies depends on what makes the case different.</p><table tabindex="0"><thead><tr><th style="text-align:right;">What makes the case different?</th><th style="text-align:right;">Where to set it</th></tr></thead><tbody><tr><td style="text-align:right;">A property known when the case is created (age, or whether it is asymptomatic), acting for the whole infection</td><td style="text-align:right;"><a href="/EpiBranch.jl/previews/PR987/api#EpiBranch.transmission_traits"><code>transmission_traits</code></a><code>(infectiousness = ...)</code></td></tr><tr><td style="text-align:right;">The state of its disease, such as only between onset and recovery, or at a funeral</td><td style="text-align:right;"><a href="/EpiBranch.jl/previews/PR987/api#EpiBranch.Infectiousness"><code>Infectiousness</code></a> windows (<code>from</code>, <code>until</code>, <code>name</code>)</td></tr><tr><td style="text-align:right;">An event that happens later (isolation, quarantine, tracing, vaccination)</td><td style="text-align:right;">an intervention, through <a href="/EpiBranch.jl/previews/PR987/api#EpiBranch.transmission_risks"><code>transmission_risks</code></a> and <a href="/EpiBranch.jl/previews/PR987/api#EpiBranch.competing_risk"><code>competing_risk</code></a></td></tr><tr><td style="text-align:right;">When in the infection transmission happens, rather than how much</td><td style="text-align:right;">the generation time, or an <code>Infectiousness</code> window&#39;s <code>kernel</code></td></tr></tbody></table><h2 id="Fixed-at-infection:-transmission_traits" tabindex="-1">Fixed at infection: <code>transmission_traits</code> <a class="header-anchor" href="#Fixed-at-infection:-transmission_traits" aria-label="Permalink to &quot;Fixed at infection: \`transmission_traits\` {#Fixed-at-infection:-transmission_traits}&quot;">​</a></h2><p><code>transmission_traits(infectiousness = ...)</code> draws a factor once, when the case is created, and scales onward transmission by it for the whole infection. The factor can be a number, a distribution or a function <code>(rng, ind) -&gt; value</code> that reads what is already known about the case. Asymptomatic cases half as infectious throughout:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">attributes </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    clinical_presentation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        incubation_period </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> LogNormal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), prob_asymptomatic </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ),</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    transmission_traits</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        infectiousness </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (rng, ind) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ind</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">state[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:asymptomatic</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.5</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> :</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>The factor cannot depend on anything that happens after the case is created. For that, use an intervention.</p><h2 id="Tied-to-disease-state:-Infectiousness-windows" tabindex="-1">Tied to disease state: <code>Infectiousness</code> windows <a class="header-anchor" href="#Tied-to-disease-state:-Infectiousness-windows" aria-label="Permalink to &quot;Tied to disease state: \`Infectiousness\` windows {#Tied-to-disease-state:-Infectiousness-windows}&quot;">​</a></h2><p>An <a href="/EpiBranch.jl/previews/PR987/api#EpiBranch.Infectiousness"><code>Infectiousness</code></a> window says between which states of the natural history a case transmits by one route, with its own offspring distribution. A case that transmits only once infectious, or by a funeral route after death, is described here. Several windows with different names give several routes.</p><h2 id="Triggered-by-an-event:-interventions" tabindex="-1">Triggered by an event: interventions <a class="header-anchor" href="#Triggered-by-an-event:-interventions" aria-label="Permalink to &quot;Triggered by an event: interventions {#Triggered-by-an-event:-interventions}&quot;">​</a></h2><p>An intervention reduces transmission from the time an event occurs, through its <code>transmission_risks</code> and <code>competing_risk</code> methods. <a href="/EpiBranch.jl/previews/PR987/api#EpiBranch.Isolation"><code>Isolation</code></a> and quarantine work this way: the factor applies from isolation onwards. A case traced at day 4 and made half as infectious from then on needs an intervention, because <code>transmission_traits</code> cannot see the tracing. <a href="./writing-interventions">Writing an intervention</a> explains how to write one, and <a href="./interventions">Isolation and contact tracing</a> covers the existing ones.</p><h2 id="About-timing:-the-generation-time" tabindex="-1">About timing: the generation time <a class="header-anchor" href="#About-timing:-the-generation-time" aria-label="Permalink to &quot;About timing: the generation time {#About-timing:-the-generation-time}&quot;">​</a></h2><p>The generation time, or the <code>kernel</code> of an <code>Infectiousness</code> window, can be any distribution or any function <code>ind -&gt; Distribution</code>. It sets when the infections of a case happen and leaves their number unchanged. Use it for infectiousness that peaks early or late, or that differs by person in its timing.</p><h2 id="Combining-them" tabindex="-1">Combining them <a class="header-anchor" href="#Combining-them" aria-label="Permalink to &quot;Combining them {#Combining-them}&quot;">​</a></h2><p>The routes multiply. A case that is asymptomatic (halved by <code>transmission_traits</code>), and traced and isolated at day 4 (by an intervention from day 4), transmits at half the baseline until day 4 and at the isolation-reduced rate after it. Use <code>transmission_traits</code> for what is true of a case from the start, and an intervention for what is true from an event on; a single factor cannot do both.</p>`,15)])])}const g=e(n,[["render",o]]);export{k as __pageData,g as default};
